// N-Sided Prism - Intersection
// https://www.shadertoy.com/view/ssBcDD

/**
 * A generalized ray-prism intersector for N number of sides.
 * Returns the near distance and the normal.
 *
 * Click and drag for interaction.
 * Mouse X position controls the rotation.
 * Mouse Y position controls the number of sides.
 * 
 *   This shader computes the intersection by looping through each plane face
 * and checking whether it is a front or a back side, and assigning it to the
 * near or far intersection respectively.
 *   Then the hit mask is computed by comparing the near and far distances.
 * Is there a name for this property?)
 * 
 *   For prisms with an even number of sides, it would be much more efficient
 * to use slab intersections instead, where the front and the backside is already known.
 * (i.e. Hexprism - intersection by iq: https://www.shadertoy.com/view/tljBWy)
 * 
 *   I've been wondering if this can be applied to subdivisions of polyhedrons,
 * maybe with octahedrons or icosahedrons.
 *   Something like Geodesic tiling by tdhooper: https://www.shadertoy.com/view/llVXRd
 * but only with just planar faces.
 * 
 *   Edit: I've just found out about this amazing shader.
 * Somebody has already done this 3 years ago T_T
 * Wish I'd seen it before writing all of these lol.
 * Looks like it's the same method but theirs is much more elegant. TT_TT
 * 
 * Truncated Icosahedron by marian42: https://www.shadertoy.com/view/ltsfzN
 * 
**/

#define MAX_SIDES 12

#define AA 2

#define MAX_DIST 1e3
#define PI 3.14159265359

#define rot2D(a) mat2(cos(a), -sin(a), sin(a), cos(a))

vec4 iPrism( vec3 o, vec3 d, float r, float he, int si )
{
    float s = float(si);
    float is = 1./s;
    float r2 = r*r;
    if (abs(o.y) > he) {
        float pl = -(o.y+he*sign(d.y))/d.y;
        vec2 plp = o.xz+d.xz*pl;
        float z;
        if ((z=length(plp)) < r) {
            float a = atan(plp.x, plp.y)+(PI*is)*mod(s+1.0, 2.0);
            if (cos(PI*is)/cos(a-2.*PI*is*floor((s*a+PI)/(2.*PI)))>z/r) return vec4(pl, 0, -sign(d.y), 0);
        }
    }
    float a = 2.0*(d.x*d.x+d.z*d.z);
    float b = 2.*(o.x*d.x+o.z*d.z);
    float disc = b*b - 2.*a*(o.x*o.x + o.z*o.z - r2);
    if (disc < 0.0) return vec4(MAX_DIST);
    disc = sqrt(disc);
    a = 1./a;
    float z = dot(o.xz, o.xz)>r2?(-b - disc)*a:0.0;
    if (z < 0.0) return vec4(MAX_DIST);
    vec2 p = o.xz+d.xz*z;
    float an = (PI+atan(p.x, p.y));
    float m = (PI*2.0)*is;
    float x = (floor(an/m)+0.5)*m;
    float fan = cos(x);
    vec2 n = vec2(sqrt(1.-fan*fan)*sign(x-PI), -fan);
    float nz =  -(dot(o.xz, n)-sqrt(2.+2.*cos(2.*PI*is))*0.5*r)/dot(d.xz, n);
    if (abs(o.y+d.y*nz) > he) return vec4(MAX_DIST);
    if (nz < z) return vec4(MAX_DIST);
    if (nz > (-b + disc)*a) return vec4(MAX_DIST);
    return vec4(nz, vec3(n.x, 0, n.y));
}

mat3 getCamMat(vec3 ro, vec3 lo)
{
    vec3 w = normalize(lo - ro);
    vec3 u = normalize(cross(w, vec3(0, 1, 0)));
    vec3 v = normalize(cross(u, w));

    return mat3(u, v, w);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 m = iMouse.xy / iResolution.xy;

    float t = iTime * 0.4;
    vec3 ro = vec3(0, 1.2, 1.8);
    vec3 lo = vec3(0, 0, 0);

    //ro.yz *= rot2D(iMouse.z > 0. ? m.y * PI+PI*2./3. : 0.);
    ro.yz *= rot2D(sin(t)*.15);
    ro.xz *= rot2D(iMouse.z > 0. ? m.x * 2.*PI : t);

    float fn = iMouse.z > 0. ? m.y : (cos(iTime*PI/2.5)*0.5+0.5);
    int n = int(fn * float(MAX_SIDES - 3)*.9999 + 3.);

    mat3 cm = getCamMat(ro, lo);

    vec3 tot = vec3(0);

    #if AA > 1
    for( int p=0; p<AA; p++ )
    for( int v=0; v<AA; v++ )
    {
        vec2 o = vec2(float(p),float(v)) / float(AA) - 0.5;
        vec2 pv = (2.0 * (fragCoord+o) - iResolution.xy) / iResolution.y;
    #else
        vec2 pv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    #endif

        vec3 col = vec3(0);

        vec3 rd = normalize(cm * vec3(pv, 1.5));

        vec4 d = iPrism(ro, rd,0.8, 0.8, n);

        if (d.x < MAX_DIST)
        {   
            vec3 p = ro + rd*d.x;
            vec3 n = d.yzw;
            vec3 l = normalize(vec3(1., .6, .5));

            vec2 uv = abs(n.y) > .5 ? p.xz : vec2(atan(p.z, p.x)/PI*2., p.y*1.2);

            vec3 env = textureLod(iChannel0, reflect(rd, n), 3.).rgb*.6+.4;
            float ch = mod(dot(floor(uv*2.5), vec2(1)), 2.)*.4+.6;
            float dif = max(dot(n, l), .1);
            col = vec3(.1, .2, .3)*.6 + vec3(.9, .8, .6)*dif*env*ch;
        } else
        {
            col = vec3(0.12)*(1.-0.45*length(pv));
        }

        tot += col;
    #if AA > 1
    }
    tot /= float(AA*AA);
    #endif

    tot = max(tot, vec3(0));
    tot = tot / (1. + tot);
    tot = pow(tot, vec3(1./2.2));

    tot += fract(sin(fragCoord.x*vec3(32,11,2)+fragCoord.y*vec3(3,31,21))*232.323)/255.;

    fragColor = vec4(tot, 1.0);
}
